package net.officefloor.hq.app;

import java.util.List;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

public class RespondWithAuditLines {
    public void respond(@PathVariable("sheetId") String sheetId,
            @RequestParam(value = "name", required = false) String name, Audit audit,
            ObjectResponse<List<String>> response) {
        response.send(audit.linesFor(sheetId, name));
    }
}
package net.officefloor.hq.app.sheet;

/** A sheet change the server refuses; answered 400 with the message. */
public class InvalidSheetRequestException extends Exception {
    public InvalidSheetRequestException(String message) {
        super(message);
    }
