import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { AMOUNT } from '../claims/useClaims';
import { templatesKey, useTemplates, type ClaimTemplate } from './useTemplates';

/**
 * The sheet's claim templates and a form to save one: a name, an amount and a note. Saving a name
 * again replaces its template; a blank name, or an amount the claim form would refuse, is refused.
 * Each person's row adds a DRAFT claim from one (see the claims feature).
 */
function TemplatesPanel({ user, sheet }: { user: string; sheet: string }) {
  const queryClient = useQueryClient();
  const { data: templates = [] } = useTemplates(sheet);
  const [name, setName] = useState('');
  const [amount, setAmount] = useState('');
  const [note, setNote] = useState('');
  const [invalid, setInvalid] = useState(false);

  const submitOnce = useSubmitOnce();
  const save = useMutation({
    mutationFn: (t: ClaimTemplate) =>
      postJson<ClaimTemplate>(`/api/sheets/${encodeURIComponent(sheet)}/claim-templates`, { ...t, user }),
    onSuccess: async () => {
      setName('');
      setAmount('');
      setNote('');
      await queryClient.invalidateQueries({ queryKey: templatesKey(sheet) });
    },
  });

  // An error goes as soon as its form is changed or submitted again.
  const clearError = () => {
    save.reset();
    setInvalid(false);
  };

  return (
    <section data-testid="templates-panel">
      <h2>Claim templates</h2>
      <form
        data-testid="template-form"
        onSubmit={(e) => {
          e.preventDefault();
          const n = name.trim();
          const a = amount.trim();
          // A template names no correction, so a negative amount is refused as the claim form would.
          if (n === '' || !AMOUNT.test(a) || a.startsWith('-')) {
            // Refused here, before anything is sent: the store and the audit file are untouched.
            save.reset();
            setInvalid(true);
            return;
          }
          setInvalid(false);
          submitOnce(() => save.mutateAsync({ name: n, amount: a, note }));
        }}
      >
        <input
          data-testid="template-form-name"
          aria-label="Template name"
          placeholder="name"
          value={name}
          onChange={(e) => {
            setName(e.target.value);
            clearError();
          }}
        />{' '}
        <input
          data-testid="template-form-amount"
          aria-label="Template amount"
          placeholder="0.00"
          value={amount}
          onChange={(e) => {
            setAmount(e.target.value);
            clearError();
          }}
        />{' '}
        <input
          data-testid="template-form-note"
          aria-label="Template note"
          placeholder="note"
          value={note}
          onChange={(e) => {
            setNote(e.target.value);
            clearError();
          }}
        />{' '}
        <button type="submit" data-testid="template-form-submit" disabled={save.isPending}>
          Save template
        </button>
        {(invalid || save.isError) && (
          <span data-testid="template-form-error" role="alert">
            {' '}
            {invalid
              ? 'Enter a name and an amount with up to two decimals, not negative.'
              : 'Could not save this template.'}
          </span>
        )}
      </form>
      <table data-testid="template-list">
        <tbody>
          {templates.map((t) => (
            <tr key={t.name} data-testid={`template-row-${t.name}`}>
              <td data-testid="template-name">{t.name}</td>
              <td data-testid="template-amount">{t.amount}</td>
              <td data-testid="template-note">{t.note}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

export const contribution = SheetPanels.fill({ order: 9, Component: TemplatesPanel });
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** A claim template as the server sends it: its name, amount (two decimals) and note. */
export type ClaimTemplate = { name: string; amount: string; note: string };

export const templatesKey = (sheet: string) => ['sheet', sheet, 'claim-templates'] as const;

/** The sheet's claim templates, by name, re-read whenever the sheet is loaded. */
export function useTemplates(sheet: string) {
  return useQuery({
    queryKey: templatesKey(sheet),
    queryFn: () => getJson<ClaimTemplate[]>(`/api/sheets/${encodeURIComponent(sheet)}/claim-templates`),
    staleTime: 0,
    gcTime: 0,
  });
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asOfKey, asOfPath, useAsOf } from '../asof/useAsOf';

/** `version` counts the person's saves; an edit sends the version it loaded, so a save made by
 *  someone else in the meantime refuses it. `statementCount` is how many statements have been
 *  taken for them; `statedTotal` the last one's due-total (two decimals, null when it was n/a or
 *  none was taken) and `statementDate` its date (yyyy-mm-dd, null when none was taken).
 *  `retired` is whether a retirement date is set (whatever the date), `retiredFrom` that date
 *  (yyyy-mm-dd, null when not retired). `held` is whether they have any hold; `holds` every hold, in the
 *  order added, from a date to a date (both inclusive; `to` null: open-ended). Their OPEN claims
 *  dated within a hold count in no live total, nor any OPEN or PENDING claim of theirs once the sheet's today
 *  reaches their retirement date, unless a statement binds them. `patrons` are the ids of the people they have named as patrons, in
 *  the order they were named. `grade` is the grade in force on the sheet's today when they were read;
 *  `grades` every grade recorded, by from-date (null: from the beginning of time, first). `terms` are
 *  the person's own terms in days (null: none), ahead of their grade's and the sheet's.
 *  `contact` is the person's contact, trimmed and lower-cased (null: none). `aliases` are the
 *  person's aliases, sorted as names are compared; the quick-add bar and the paste box find a
 *  person by an alias as well as by the name. */
export type Person = {
  id: number;
  name: string;
  grade: string;
  grades: { grade: string; from: string | null }[];
  version: number;
  statementCount: number;
  statedTotal: string | null;
  statementDate: string | null;
  retired: boolean;
  retiredFrom: string | null;
  held: boolean;
  holds: { from: string; to: string | null }[];
  patrons: number[];
  terms: number | null;
  contact: string | null;
  aliases: string[];
};

/** Whether the sheet's `today` (yyyy-mm-dd) has reached the person's retirement date. */
export function retiredOut(person: Person, today: string): boolean {
  return person.retiredFrom !== null && today !== '' && today >= person.retiredFrom;
}

/** Whether a claim of the person's dated `date` (yyyy-mm-dd) is held out of the live totals: the date
 *  falls within any of the person's holds, or the sheet's `today` has reached their retirement date. */
export function heldOn(person: Person, date: string, today: string): boolean {
  return retiredOut(person, today) || person.holds.some((h) => date >= h.from && (h.to === null || date <= h.to));
}

/** By person id, whether a claim dated then is held out (see `heldOn`) on the sheet's `today`. */
export function heldOnBy(people: Person[], today: string): (personId: number, date: string) => boolean {
  const byId = new Map(people.map((p) => [p.id, p]));
  return (personId, date) => {
    const p = byId.get(personId);
    return p !== undefined && heldOn(p, date, today);
  };
}

export const GRADES = ['A', 'B', 'C'] as const;

export const peopleKey = (sheet: string) => ['sheet', sheet, 'people'] as const;

